<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow &mdash; Mondrian, 1930</title>
<meta name="description" content="The story of Piet Mondrian's Composition with Red, Blue and Yellow (1930) and the De Stijl movement.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;600;800;900&display=swap" rel="stylesheet">
<style>
  :root {
    --red: #d40119;
    --blue: #0a3fb8;
    --yellow: #f7ce00;
    --ink: #0b0b0b;
    --paper: #ffffff;
    --line: 10px;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    font-family: "Archivo", Arial, sans-serif;
    background: var(--paper);
    color: var(--ink);
    line-height: 1.55;
  }

  .wrap { max-width: 1100px; margin: 0 auto; }

  /* ---------- Hero: Mondrian grid ---------- */
  .hero {
    display: grid;
    grid-template-columns: 1.15fr 0.85fr 0.6fr;
    grid-template-rows: auto auto;
    border-bottom: var(--line) solid var(--ink);
  }
  .hero > * { border-right: var(--line) solid var(--ink); }
  .hero > *:last-child { border-right: 0; }

  .hero-copy {
    grid-column: 1 / 3;
    padding: clamp(2rem, 6vw, 4.5rem);
    border-bottom: var(--line) solid var(--ink);
  }
  .kicker {
    display: inline-block;
    font-weight: 800;
    font-size: 0.8rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    border: 4px solid var(--ink);
    padding: 0.35rem 0.7rem;
    margin-bottom: 1.4rem;
    background: var(--paper);
  }
  h1 {
    font-weight: 900;
    font-size: clamp(2.1rem, 5.5vw, 4.2rem);
    line-height: 1.02;
    letter-spacing: -0.02em;
    text-transform: uppercase;
    max-width: 16ch;
  }
  h1 .r { color: var(--red); }
  h1 .b { color: var(--blue); }
  h1 .y { color: var(--yellow); -webkit-text-stroke: 2px var(--ink); }
  .hero-sub {
    margin-top: 1.4rem;
    max-width: 46ch;
    font-size: clamp(1rem, 1.6vw, 1.2rem);
    font-weight: 400;
  }
  .hero-cta { margin-top: 2rem; display: flex; gap: 1rem; flex-wrap: wrap; }

  .hero-red {
    grid-column: 3;
    grid-row: 1 / 3;
    background: var(--red);
    min-height: 220px;
  }
  .hero-blue {
    grid-column: 1;
    background: var(--blue);
    min-height: 150px;
  }
  .hero-yellow {
    grid-column: 2;
    background: var(--yellow);
    min-height: 150px;
  }

  /* ---------- Buttons ---------- */
  .btn {
    display: inline-block;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-size: 0.95rem;
    text-decoration: none;
    padding: 0.9rem 1.6rem;
    border: var(--line) solid var(--ink);
    color: var(--ink);
    background: var(--yellow);
    box-shadow: 8px 8px 0 var(--ink);
    transition: transform 0.12s ease, box-shadow 0.12s ease;
  }
  .btn:hover, .btn:focus-visible {
    transform: translate(4px, 4px);
    box-shadow: 4px 4px 0 var(--ink);
  }
  .btn--red { background: var(--red); color: #fff; }
  .btn--ghost { background: var(--paper); }

  /* ---------- Sections as grid blocks ---------- */
  section { border-bottom: var(--line) solid var(--ink); }
  .band { padding: clamp(2rem, 5vw, 4rem); }

  h2 {
    font-weight: 900;
    text-transform: uppercase;
    font-size: clamp(1.4rem, 3vw, 2.2rem);
    letter-spacing: -0.01em;
    margin-bottom: 1rem;
  }
  h2 .tag { display: inline-block; width: 1.1em; height: 1.1em; margin-right: 0.45em; border: 5px solid var(--ink); vertical-align: -0.12em; }
  .tag--red { background: var(--red); }
  .tag--blue { background: var(--blue); }
  .tag--yellow { background: var(--yellow); }
  p + p { margin-top: 0.9rem; }

  .two-col {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }
  .two-col > * { border-right: var(--line) solid var(--ink); }
  .two-col > *:last-child { border-right: 0; }


